const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Onemen Bay is a large, shallow bay in Chukotka Autonomous Okrug, Russia.
  const geometry = ee.Geometry.Polygon(
    [[[175.5, 64.9], [177.2, 64.9], [177.2, 64.5], [175.5, 64.5], [175.5, 64.9]]],
    null, false
  );
  const date1_start = '2025-08-09';
  const date1_end = '2025-08-10';
  const date2_start = '2025-09-11';
  const date2_end = '2025-09-12';

  // 2. Data Acquisition & Check
  // The question asks about future dates (2025). GEE contains historical data.
  // This will result in an empty collection.
  const s2_collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED');

  const col1 = s2_collection.filterBounds(geometry).filterDate(date1_start, date1_end);
  const col2 = s2_collection.filterBounds(geometry).filterDate(date2_start, date2_end);

  const col1_size = col1.size().getInfo();
  const col2_size = col2.size().getInfo();

  console.log(`Images found for Aug 2025: ${col1_size}`);
  console.log(`Images found for Sep 2025: ${col2_size}`);

  // This check is crucial as the dates are in the future.
  if (col1_size === 0 || col2_size === 0) {
    console.log("Error: No satellite imagery exists for future dates.");
    console.log("C1");
    return;
  }

  // The code below will not be executed due to the check above,
  // but is included to demonstrate the full logic for a valid date range.

  // 3. Processing
  const cloudMask = function(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    let mask = qa.bitwiseAnd(cloudBitMask).eq(0)
      .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask).divide(10000);
  };

  const addNDVI = function(image) {
    const ndvi = image.normalizedDifference(['B8', 'B4']).rename('NDVI');
    return image.addBands(ndvi);
  };

  const image1 = col1.map(cloudMask).map(addNDVI).median();
  const image2 = col2.map(cloudMask).map(addNDVI).median();

  // 4. Calculation
  const scale = 3000;
  const ndvi1_stats = image1.select('NDVI').reduceRegion({
    reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
    }),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  });
  const ndvi2_stats = image2.select('NDVI').reduceRegion({
    reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
    }),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  });

  const ndvi1 = ndvi1_stats.get('NDVI_mean').getInfo();
  const ndvi1_pixels = ndvi1_stats.get('NDVI_count').getInfo();

  const ndvi2 = ndvi2_stats.get('NDVI_mean').getInfo();
  const ndvi2_pixels = ndvi2_stats.get('NDVI_count').getInfo();

  // 5. Validation & Final Answer
  if (ndvi1_pixels === 0 || ndvi2_pixels === 0) {
    console.log(`Valid pixels Aug 2025: ${ndvi1_pixels}`);
    console.log(`Valid pixels Sep 2025: ${ndvi2_pixels}`);
    console.log("C2");
    return;
  }

  if (ndvi1 === null || ndvi2 === null) {
    console.log("Calculation failed, result is null.");
    console.log("C3");
    return;
  }

  console.log(`Aug 2025 Mean NDVI: ${ndvi1.toFixed(4)}, Pixels: ${ndvi1_pixels}`);
  console.log(`Sep 2025 Mean NDVI: ${ndvi2.toFixed(4)}, Pixels: ${ndvi2_pixels}`);

  if (ndvi1 > ndvi2) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
      ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
      ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (e) {
    console.error(`Error: ${e.toString()}`);
    console.log("D");
  }
}

initEE();
